function cloudEndpoint(){return new URL('/api/ghost',location.href).href;}
function localGuideChosen(){try{return localStorage.getItem('ghost-ai-disabled')==='1';}catch{return false;}}
function showAIStatus(){
 const owner=state.apiAccess===true;
 for(const id of ['aiKey','connectAiBtn','testAiBtn','removeAiKeyBtn'])$(id).hidden=!owner;
 $('aiKey').closest('label').hidden=!owner;
 $('aiAccessNotice').hidden=owner;
 $('connectAiBtn').disabled=!owner;
 const saved=!!state.aiInfo?.aiConfigured,verified=!!state.aiInfo?.apiVerified;
 $('aiKeyState').textContent=saved?'A key is saved. Leave the field empty and tap Test Ghost.':'No key is saved yet. Paste your key above and save the connection.';
 $('aiKey').placeholder=saved?'A key is saved — paste only to replace it':'Paste your existing key here';
 $('aiStatus').textContent=state.connected?(verified?'Ghost online · ':'Key saved · ')+(state.aiInfo?.model||'OpenAI'):saved?'Local guide · online key saved':'Local engineer · connect Ghost for AI';
 $('chatMode').textContent=state.connected?'Chat + measurements shared · local DAW commands stay free':'Local guide · no AI charges';
 $('aiUsage').textContent=window.GhostAI.usageText(state.aiInfo);
 $('testAiBtn').disabled=!saved||!!state.aiInfo?.blocked;
 $('removeAiKeyBtn').disabled=!owner||!saved;
 if(!owner){$('aiKey').value='';$('aiKeyState').textContent='API access is reserved for the studio owner.';$('aiUsage').textContent='Local tools do not use the OpenAI API.';$('aiStatus').textContent='Local engineer · owner-only API';}
 window.dispatchEvent(new Event('ghost-ai-state'));
}
function applyCloudStatus(info,enabled=true){
 if(typeof info?.canUseApi==='boolean')state.apiAccess=info.canUseApi;
 state.aiInfo=info;state.connected=state.apiAccess===true&&enabled&&!!info?.aiConfigured&&!info?.blocked;
 state.endpoint=state.connected?cloudEndpoint():'';showAIStatus();
}
async function connectAI(){
 if(state.apiAccess!==true){$('aiConnectionResult').textContent='Only the studio owner can activate or use the API.';return;}
 const epoch=++state.aiConnectionEpoch;let key=$('aiKey').value.trim();$('aiKey').value='';
 $('connectAiBtn').disabled=true;$('aiConnectionResult').textContent=key?'Saving your private connection…':'Checking your saved connection…';
 try{
  const info=key?await window.GhostCloud.save(key): (await window.GhostAI.inspect(cloudEndpoint(),{base:location.href})).status;key='';
  if(epoch!==state.aiConnectionEpoch)return;
  try{localStorage.removeItem('ghost-ai-disabled');}catch{}
  applyCloudStatus(info);
  $('aiConnectionResult').textContent=info.blocked?'Online requests are paused for a usage review.':!info.aiConfigured?'Paste your existing OpenAI key into the private field above.':info.apiVerified?'Your saved connection is ready.':'Key saved. Tap Test Ghost to check API access.';
 }catch(e){if(epoch!==state.aiConnectionEpoch)return;state.connected=false;state.endpoint='';showAIStatus();$('aiConnectionResult').textContent=window.GhostAI.errorText(e);}
 finally{key='';showAIStatus();}
}
async function testGhostConnection(){
 if(state.apiAccess!==true){$('aiConnectionResult').textContent='Only the studio owner can activate or use the API.';return;}
 const epoch=++state.aiConnectionEpoch;$('testAiBtn').disabled=true;$('aiConnectionResult').textContent='Testing Ghost with one short API request…';
 try{const data=await window.GhostAI.request(cloudEndpoint(),{message:'Reply with exactly: Ghost is connected and ready.',history:[],context:{}},{base:location.href});if(epoch!==state.aiConnectionEpoch)return;try{localStorage.removeItem('ghost-ai-disabled');}catch{}applyCloudStatus(data.budget);$('aiConnectionResult').textContent='Connected. Ghost replied: '+data.reply;}
 catch(e){if(epoch!==state.aiConnectionEpoch)return;if(e.budget)state.aiInfo=e.budget;state.connected=false;state.endpoint='';$('aiConnectionResult').textContent=window.GhostAI.errorText(e);}
 finally{showAIStatus();}
}
async function removeGhostKey(){
 if(state.apiAccess!==true){$('aiConnectionResult').textContent='Only the studio owner can activate or use the API.';return;}
 const epoch=++state.aiConnectionEpoch;$('removeAiKeyBtn').disabled=true;$('aiKey').value='';
 try{const info=await window.GhostCloud.remove();if(epoch!==state.aiConnectionEpoch)return;applyCloudStatus(info);$('aiConnectionResult').textContent='The key was removed from online Ghost. It was not revoked at OpenAI. Your usage history is preserved.';}
 catch(e){$('aiConnectionResult').textContent=window.GhostAI.errorText(e);}finally{showAIStatus();}
}
async function connectBundledService(){
 const epoch=state.aiConnectionEpoch;
 try{const result=await window.GhostAI.inspect(cloudEndpoint(),{base:location.href});if(epoch!==state.aiConnectionEpoch)return;applyCloudStatus(result.status,!localGuideChosen());$('aiConnectionResult').textContent=result.status.canUseApi===false?'Only the studio owner can activate or use the API. You can continue with the local tools.':result.status.aiConfigured?(result.status.apiVerified?'Your saved connection is ready.':'Key saved. Tap Test Ghost to check API access.'):'Save your existing OpenAI key once to use Ghost on this website.';}
 catch(e){if(epoch!==state.aiConnectionEpoch)return;state.apiAccess=false;state.connected=false;state.endpoint='';showAIStatus();$('aiConnectionResult').textContent=window.GhostAI.errorText(e);}
}
const knowledge=[
 {terms:/\b(compress|compressor|compression|ratio|threshold|attack|release)\b/i,text:'Compression reduces signal above its threshold according to the ratio. Start gently: 2:1 or 3:1. A slower attack preserves more transient impact; a faster attack catches more peaks. Set release while listening to the groove. Compare at similar output levels. The workshop exposes threshold, ratio, attack, release, knee and makeup gain.',target:'forge'},
 {terms:/\b(eq|equaliz|frequency|mud|muddy|rumble|harsh|bright|air)\b/i,text:'Use the high-pass filter for unwanted low rumble, a parametric EQ for a focused problem, and shelves for broad tonal balance. Sweep while listening, then make the smallest useful change. A vocal starting point is a gentle low cut around 70 Hz, but a bass or kick needs different treatment. Analyze your selected source before choosing a correction.',target:'inspector'},
 {terms:/\b(lufs|loudness|mastering|master|spotify|music sites|release|ready|distribution|true peak)\b/i,text:'Master Rack Pro combines your eight mastering stages in fixed order. It starts at zero with bypass on. The master meter shows estimated momentary LUFS and 4× true peak. Export can attenuate the render to its estimated peak target. These meters are not certified and do not measure integrated LUFS. Use a matched listening reference and verify the destination’s delivery requirements before release.',target:'exportBtn'},
 {terms:/\b(pan|stereo|mono|phase|width)\b/i,text:'Pan positions a stem between left and right. Keep essential low-end and lead material stable unless you have a reason to move it. Two stereo channels can partially cancel when summed to mono. Negative sampled correlation is a reason to investigate, not an automatic fault diagnosis. This edition does not include a dedicated mono monitor switch.',target:'mixer'},
 {terms:/\b(noise|hiss|click|crackle|de.?ess|sibilance)\b/i,text:'Stem Cleanup reduces steady background noise using a quiet-section estimate and can repair isolated single-sample clicks. Say “remove noise and artifacts” to measure and apply conservative cleanup. It cannot reconstruct clipped source audio or guarantee removal of all generated artifacts. This app no longer synthesizes tape hiss or adds dither to export. De-essing is a separate consonant-control task.',target:'forge'},
 {terms:/\b(export|download|wav|bit depth|sample rate)\b/i,text:'Export mix opens offline stereo WAV rendering. Choose 44.1 or 48 kHz and 16/24-bit PCM or 32-bit float. Range and aligned stem export are available. Audible mix follows mute and solo. Selected stem export includes the master trim. Effects and their tails are rendered, and estimated true-peak protection only turns the result down when necessary. Use the download button once rendering finishes.',target:'exportBtn'},
 {terms:/\b(save|project|backup|open session)\b/i,text:'Save keeps one session in this browser, including its source audio, MIDI notes, chat and effects. Projects lets you open that session or download a portable .ghostproject backup. A downloaded backup is the reliable way to keep your work if browser storage is cleared.',target:'projectBtn'},
 {terms:/\b(plugin|effect|workshop|forge|create|build)\b/i,text:'Plugin workshop contains your 16 vocal/mastering plugins, Master Rack Pro, Stem Cleanup and a custom chain builder. New inserts are zero-neutral and bypassed. Choose a factory sound only when you want processing. Use the destination selector for a stem or master bus, then Edit in that rack for live controls, A/B, automation and MIDI learn. A Ghost plugin is an in-app processor or chain, not a VST/AU binary.',target:'forge'},
 {terms:/\b(tempo|bpm|beat|stretch|pitch|key)\b/i,text:'BPM controls the grid, MIDI note timing and Throw Delay Vox tempo sync. It does not change imported audio speed or musical key. Vocal Doubler Wide uses small pitch shifts and delays for doubling, but this edition does not provide general pitch correction or time stretching.',target:'bpmInput'},
 {terms:/\b(trim|split|arrange|move|timeline)\b/i,text:'Select a stem. Drag its waveform horizontally to move it, or enter exact seconds in Track detail. Trim in and out refer to source seconds. Click the ruler to seek, then Split at playhead to divide the selected clip into two independently mixable pieces. Undo restores the last edit.',target:'arrangement'},
 {terms:/\b(hello|hey|hi|help|what can|who are)\b/i,text:'I’m Ghost in the Machine, your local console guide. I can explain this DAW, measure a selected stem and offer effect starting points. Commands include apply needed plugins, remove noise and artifacts, play, pause, stop, analyze, mute, unmute, solo, unsolo, and “set volume to -6 dB” for the selected stem. Connect an AI service for broader conversation.',target:'ghostPanel'}
];
async function assistantRequest(message){const request=window.GhostAssistant.intent(message);if(!request)return null;if(request.kind==='decline')return 'No plugins applied. Your settings are unchanged.';
 return busy(request.kind==='apply'?'Measuring and preparing clean processing…':'Measuring your stems…',async()=>{await engine.idle();const progress=message=>$('busyText').textContent=message,plan=await window.GhostAssistant.plan(engine,state.selected,request,progress);if(request.kind==='suggest'){for(const i of plan.items)i.track.analysis=i.measurement;return window.GhostAssistant.describe(plan,false);}await window.GhostAssistant.checkOutput(engine,plan,progress);const reply=await window.GhostAssistant.apply(engine,plan,snapshot);pluginUI?.resetEditing();renderAll();const current=plan.items.find(i=>i.track.id===state.selected);if(current)showAnalysis(current.track,current.measurement);return reply;});
}
async function localReply(message){const pluginRequest=window.GhostPluginCommands.parse(message);if(pluginRequest){try{return await window.GhostPluginCommands.execute(message,{engine,selectedId:state.selected,snapshot});}finally{pluginUI?.resetEditing();renderAll();}}const playback=window.GhostAssistant.playbackHelp(message,engine);if(playback!==null){spotlight(engine.tracks.some(t=>t.midi||t.demo)?'sourceNotice':'arrangement',playback);return playback;}const composition=await studioTools.chat(message);if(composition!==null)return composition;const action=await assistantRequest(message);if(action!==null)return action;const lower=message.trim().toLowerCase().replace(/[.!?]+$/,'');if(/^(play|start playback|pause|stop)$/.test(lower)){if(lower==='pause'){await studioTools.stopRecording();engine.pause();}else if(lower==='stop'){await studioTools.stopRecording();engine.stop();}else await engine.play();return lower==='pause'?'Playback paused.':lower==='stop'?'Stopped and returned to 0:00.':'Playing your current session.';}
 if(/^(analy[sz]e|analy[sz]e stem|analy[sz]e this|check my stem|check this stem)$/.test(lower)){await analyzeSelected();const t=selected(),a=t.analysis;return t.name+' peaks at '+a.peakDb.toFixed(1)+' dBFS with an RMS level of '+a.rmsDb.toFixed(1)+' dBFS. The source report and starting-point suggestions are above.';}
 if(/^(mute|unmute|solo|unsolo)( selected( stem| track)?)?$/.test(lower)){const t=selected();if(!t)throw Error('Select a stem first.');snapshot();const key=lower.includes('solo')?'solo':'mute';t[key]=!lower.startsWith('un');engine.update();renderMixer();renderTimeline();return t.name+': '+key+' '+(t[key]?'on.':'off.');}
 const volume=lower.match(/^(?:set )?(?:volume|gain)(?: to)? (-?\d+(?:\.\d+)?)\s*(?:db)?$/);if(volume){const t=selected();if(!t)throw Error('Select a stem first.');const v=Number(volume[1]);if(v<-60||v>12)throw Error('Track gain is between -60 and +12 dB.');snapshot();t.gainDb=v;if(t.trackAutomation?.gainDb)t.trackAutomation.gainDb.enabled=false;engine.update();renderMixer();return t.name+' is set to '+v.toFixed(1)+' dB.';}
 const plugin=Object.values(window.GhostPacks.definitions).find(d=>lower.includes(d.name.toLowerCase())||(d.type==='masterrack'&&lower.includes('master rack pro')));if(plugin){if(/^(insert|add)\b/.test(lower)){await pluginUI.insert([A.newEffect(plugin.type)],plugin.name);return plugin.name+' was added at zero with bypass on. Open its rack to activate a preset or adjust it.';}showView('forge');return plugin.name+': '+plugin.description+' It starts at zero and bypassed. Available sound presets: '+plugin.factory.map(p=>p.name).join(', ')+'.';}
 const match=knowledge.find(k=>k.terms.test(message));if(match){if(match.target==='forge')showView('forge');else spotlight(match.target,match.text);return match.text;}return 'I’m not sure how to answer that with the local guide. I can explain EQ, compression, panning, this DAW’s controls, plugins and export, or analyze a selected stem. Connect your AI service for open-ended music conversation. I have not heard or analyzed your audio unless a measurement report is shown.';
}
async function sendChat(){const text=$('chatInput').value.trim();if(!text||$('sendChatBtn').disabled)return;$('chatInput').value='';addChat('user',window.GhostLyrics.isRequest(text)?'Opened a temporary lyrics request.':text);$('sendChatBtn').disabled=true;$('ghostActivity').textContent='Checking your request…';try{if(window.GhostLyrics.isRequest(text)){const message=await workspacePages.fromChat(text);if(message)addChat('ghost',message);return;}const reply=await window.GhostAssistant.dispatch(text,{local:localReply,remote:state.endpoint?async message=>{const endpoint=state.endpoint;try{const reply=await remoteChat(message,endpoint);if(state.endpoint===endpoint)state.connected=true;showAIStatus();return reply;}catch(e){if(state.endpoint===endpoint)state.connected=false;showAIStatus();return 'The AI service could not answer: '+e.message+'\nDAW commands, including “apply needed plugins”, still work locally.';}}:null});if(reply)addChat('ghost',reply);}catch(e){addChat('ghost',e.message);}finally{$('sendChatBtn').disabled=false;}}

